contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will drive Put to deposit funds, possibly set MinSum=0 and ensure unlockTime in past by using Put with 0 lock
    // Then attempt Collect and check the effect on Acc(msg.sender).balance and address(c).balance.
    // Parameters:
    //   uint deposit - amount of wei to Put into c (sent from this test)
    //   uint collectAmt - amount of wei to attempt to Collect
    //   uint setMin - value to set as MinSum (we call SetMinSum once if needed)
    function run(uint deposit, uint collectAmt, uint setMin) public payable {
        require(address(this).balance >= deposit, "insufficient balance for deposit");

        // Ensure MinSum set to setMin if contract not yet initialized
        // We call SetMinSum; it may revert if Initialized() already called in c, so catch via try/catch pattern
        bool setMinReverted;
        try c.SetMinSum(setMin) {
            setMinReverted = false;
        } catch {
            setMinReverted = true;
        }

        // Do a Put from this test to deposit into Acc[msg.sender]
        c.Put{value: deposit}(0);

        // Read balance before collect via auto getter Acc(msg.sender).balance: Acc is public mapping of Holder struct; Solidity generates a getter Acc(address) -> (unlockTime, balance)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // The invariant to assert:
        // If Collect succeeded (not reverted) then beforeBal >= setMin, beforeBal >= collectAmt, and block.timestamp > beforeUnlock
        // and afterBal == beforeBal - collectAmt and contract balance decreased by collectAmt.
        // If Collect reverted then balances unchanged.
        assert(
            (!collectReverted && afterBal + collectAmt == beforeBal && contractBalBefore == contractBalAfter + collectAmt)
            || (collectReverted && afterBal == beforeBal && contractBalBefore == contractBalAfter)
        );
    }

    receive() external payable {}
}

