    // Test that Put{value: v}(lock) always increases the caller's recorded balance and the contract balance by v
    // Parameters:
    //   uint v - amount of wei to send with Put
    //   uint lock - lock time argument passed to Put
    function run(uint v, uint lock) public payable {
        require(address(this).balance >= v, "insufficient balance for call");

        // Read before-values via public getter Acc(address) -> (unlockTime, balance)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // Perform Put sending v wei; capture revert if any
        bool putReverted;
        try c.Put{value: v}(lock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // If Put succeeded then both balances must have increased by exactly v and unlockTime must be >= beforeUnlock
        // If Put reverted then nothing observable on c changed (balances and unlockTime unchanged)
        assert(
            (!putReverted && afterBal == beforeBal + v && contractBalAfter == contractBalBefore + v && afterUnlock >= beforeUnlock)
            || (putReverted && afterBal == beforeBal && contractBalAfter == contractBalBefore && afterUnlock == beforeUnlock)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
