    constructor(C _c) { c = _c; }

    // Test parameters:
    //   uint am - amount to attempt to Collect
    // We do not send Ether to Collect (Collect is payable but uses msg.sender.call for payment out).
    function run(uint am) public payable {
        // No precondition on am; avoid doing arithmetic that can under/overflow in this test contract's asserts.
        // Read before-values via public getter Acc(address) -> (unlockTime, balance)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // Attempt to Collect and catch whether it reverted
        bool collectReverted;
        try c.Collect(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule asserted:
        // - If Collect reverted: contract balance and recorded holder entry remain unchanged.
        // - If Collect succeeded: contract balance is either unchanged (if _am==0) or decreased by exactly am,
        //   and the caller's recorded balance did not increase (i.e., afterBal >= beforeBal is allowed but we require it is not greater than beforeBal + 0 -> equivalently afterBal <= beforeBal).
        // To avoid subtraction underflow in the assert, we express decrease as contractBalAfter == contractBalBefore || contractBalBefore == contractBalAfter + am
        // and for holder balance we require afterBal <= beforeBal.
        assert(
            (collectReverted && afterBal == beforeBal && contractBalAfter == contractBalBefore && afterUnlock == beforeUnlock)
            || (!collectReverted && afterBal <= beforeBal && (contractBalAfter == contractBalBefore || contractBalBefore == contractBalAfter + am))
        );
    }

    // accept Ether when the contract receives refunds from c
    receive() external payable {}
}

