        // Read before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // Call Put and capture revert flag
        bool putReverted;
        try c.Put{value: amount}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // If Put reverted then nothing observable on c must have changed.
        // If Put succeeded then both the per-address recorded balance and contract balance increased by exactly amount.
        // Express increase without subtraction to avoid underflow: after == before || after == before + amount
        assert(
            (putReverted && afterBal == beforeBal && contractBalAfter == contractBalBefore && afterUnlock == beforeUnlock)
            || (!putReverted && afterBal == (beforeBal + amount) && contractBalAfter == (contractBalBefore + amount))
        );
    }

    // allow receiving Ether refunds if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to Put some Ether, then possibly Collect an amount; it asserts that when Collect succeeded
    // the stored balance for this contract's address decreased by the collected amount and address(c).balance also decreased by >= that amount.
    function run(uint putLock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for put");
        // initial observations
        uint beforeContractBal = address(c).balance;
        (, uint beforeHolderBal) = c.Acc(address(this));

        // perform Put: send Ether to c from this contract
        c.Put{value: putAmount}(putLock);

        // observe after Put
        uint afterPutContractBal = address(c).balance;
        (, uint afterPutHolderBal) = c.Acc(address(this));

        // now attempt Collect for collectAmount and record whether it reverted
        bool collectReverted;
        uint afterCollectContractBal;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        collectReverted = !ok;
        afterCollectContractBal = address(c).balance;
        (, uint afterHolderBal) = c.Acc(address(this));

        // If Collect succeeded (did not revert) then the holder balance must have decreased by exactly collectAmount
        // and the contract balance must have decreased by at least collectAmount (it may decrease by more in other cases,
        // but for this contract it should be exactly collectAmount; we assert >= to be robust).
        assert(collectReverted || (afterPutHolderBal == beforeHolderBal + putAmount && // sanity: Put increased holder balance by putAmount
               afterHolderBal + collectAmount == afterPutHolderBal && // holder balance decreased exactly by collectAmount
               afterCollectContractBal + collectAmount <= afterPutContractBal));
    }

    // allow receiving Ether so this test contract can hold funds to call c.Put
    receive() external payable {}
}

contract InvMutTest {
