    // Single public test function: try a Put then attempt Collect; assert the invariant when Collect succeeds.
    function run(uint putLock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for put");

        // Observe before any calls
        uint beforeContractBal = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));
        uint beforeMin = c.MinSum();

        // Perform Put: must be a top-level state-changing call
        c.Put{value: putAmount}(putLock);

        // Read state after Put and before Collect
        (uint midUnlock, uint midHolderBal) = c.Acc(address(this));
        uint midMin = c.MinSum();
        uint midContractBal = address(c).balance;

        // Attempt Collect as a top-level call and capture whether it reverted by using try/catch
        bool collectReverted;
        // try/catch on external call
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read holder balance and contract balance after Collect (even if Collect reverted, values reflect final state)
        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assert the general rule: if Collect succeeded then pre-Collect holder balance (midHolderBal)
        // was >= MinSum and >= collectAmount, and afterHolderBal == midHolderBal - collectAmount.
        // We also assert that Put increased the holder balance by exactly putAmount.
        assert(
            midHolderBal == beforeHolderBal + putAmount &&
            (collectReverted || (midHolderBal >= midMin && midHolderBal >= collectAmount && afterHolderBal + collectAmount == midHolderBal))
        );
    }

    // allow receiving Ether so this test contract can fund Put and receive Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test: call Put with a value and assert contract and Acc balances do not decrease
    function run(uint putLock, uint putAmount) public payable {
        // ensure this test contract has enough Ether to send
        require(address(this).balance >= putAmount, "insufficient test balance");

        // observe before values
        uint beforeContractBal = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));

        // perform Put as top-level state-changing call
        c.Put{value: putAmount}(putLock);

        // observe after values
        uint afterContractBal = address(c).balance;
        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));

        // General rule: after Put the contract's balance and the holder's recorded balance are each >= before,
        // and each increased by at most the amount we sent (no unexpected extra increase), and the holder's recorded
        // increase is exactly the amount we sent (i.e., the contract records the deposit for the sender).
        // We avoid subtraction that could under/overflow by using comparisons and additivity checks.
        assert(
            // balances never decrease
            afterContractBal >= beforeContractBal &&
            afterHolderBal >= beforeHolderBal &&
            // contract balance increases by at most putAmount
            afterContractBal <= beforeContractBal + putAmount &&
            // holder recorded balance increases by at most putAmount
            afterHolderBal <= beforeHolderBal + putAmount &&
            // holder recorded balance increased by exactly putAmount (the contract must credit msg.sender)
            afterHolderBal == beforeHolderBal + putAmount
        );
    }

    // allow receiving Ether so this test contract can fund Put and receive any refunds
    receive() external payable {}
}

