contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test: try to Collect and assert the balance effects when it doesn't revert.
    function run(uint am) public payable {
        // No precondition on am; but to allow Collect to possibly succeed, ensure the test contract
        // can fund the c contract and also set up Acc[msg.sender] to meet MinSum etc.
        // Step 1: fund this test contract if needed is not possible here, but we can fund c by calling Put with some value.
        // Ensure we have some ETH to call Put: require the test transaction provides it if needed.
        // We'll use half of available balance for Put to avoid overflows in our bookkeeping.
        uint have = address(this).balance;
        uint putAmt = have;
        if (putAmt > 0) {
            // call Put to increase Acc[this] and address(c).balance
            c.Put{value: putAmt}(0);
        }

        // Read observable before-values
        uint beforeContractBal = address(c).balance;
        (, uint beforeHolderBal) = c.Acc(address(this));
        uint beforeMin = c.MinSum();

        // Attempt Collect; capture whether it reverted
        bool reverted = false;
        // top-level state-changing call must be direct; use try/catch on low-level call to record revert
        try c.Collect{value: 0}(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterContractBal = address(c).balance;
        (, uint afterHolderBal) = c.Acc(address(this));

        // General rule: if Collect succeeded (didn't revert) then beforeHolderBal >= beforeMin && beforeHolderBal >= am && block.timestamp > the stored unlockTime must have been true at call time (we cannot read unlockTime directly here except via Acc), but we can at least assert numeric balance relations:
        // - If not reverted, holder's recorded balance decreased by exactly am
        // - If not reverted, contract balance decreased by at least am
        // If reverted, no requirement about balances (they may or may not change depending on internal behavior), so we allow either.
        assert(
            reverted || (
                // when succeeded: beforeHolderBal was sufficient and balances updated correctly
                afterHolderBal + am == beforeHolderBal &&
                beforeContractBal >= afterContractBal &&
                beforeContractBal - afterContractBal >= am
            )
        );
    }

    receive() external payable {}
}

