contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run simulates a user sending funds via Put and then attempting Collect.
    // params:
    //   putAmount - Ether to send to Put
    //   lockTime  - lock time parameter for Put
    //   collectAmount - requested amount to Collect
    // The contract must be funded to send putAmount to c.
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance to Put");
        // ensure MinSum is small so Collect's MinSum condition may pass; set to 0 if possible
        // We call SetMinSum only if not initialized. It's allowed to revert; ignore that.
        // Must call top-level state-changing calls separately.
        // Attempt to set MinSum to 0 (may revert if already initialized) - allowed as top-level.
        try c.SetMinSum(0) {
        } catch {}

        // Record c balance before Put
        uint beforeCbal = address(c).balance;
        // Record holder balance before Put via public mapping getter: Acc is public so Acc(address) returns Holder tuple (unlockTime,balance)
        (uint beforeUnlockTime, uint beforeHolderBalance) = c.Acc(address(this));

        // Call Put sending putAmount wei
        c.Put{value: putAmount}(lockTime);

        // After Put, get balances
        uint afterCbal = address(c).balance;
        (uint afterUnlockTime, uint afterHolderBalance) = c.Acc(address(this));

        // Now attempt Collect of collectAmount. We must call it and capture whether it reverted.
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read state after Collect
        uint finalCbal = address(c).balance;
        (uint finalUnlockTime, uint finalHolderBalance) = c.Acc(address(this));

        // The general invariant to assert:
        // If Collect did not revert, and the external call sent by Collect succeeded (i.e., msg.sender.call returned true),
        // then the holder's recorded balance must have decreased by exactly collectAmount and the contract balance must have decreased by at least collectAmount.
        // We cannot directly observe success of internal call return value, but Collect only updates balances when the low-level call returned true.
        // Therefore we assert: if Collect did not revert, then finalHolderBalance == afterHolderBalance - (collectReverted ? 0 : (collectAmount <= afterHolderBalance ? collectAmount : 0))
        // More directly: if Collect did not revert and afterHolderBalance >= collectAmount and afterHolderBalance >= c.MinSum() and block time > unlockTime
        // then finalHolderBalance == afterHolderBalance - collectAmount and finalCbal + collectAmount <= afterCbal (contract lost at least collectAmount).

        // Read MinSum and current block.timestamp via view; block.timestamp is available here as current tx timestamp.
        uint minSum = c.MinSum();

        // Compute condition under which Collect is allowed by contract logic (pre-conditions inside Collect):
        bool collectAllowedByLogic = (afterHolderBalance >= minSum) && (afterHolderBalance >= collectAmount) && (block.timestamp > afterUnlockTime);

        // If Collect did not revert and the logical conditions held, then Collect must have succeeded in sending funds and updating balances.
        // So assert that finalHolderBalance == afterHolderBalance - collectAmount and finalCbal + collectAmount <= afterCbal.
        assert(
            (!collectReverted && collectAllowedByLogic) ?
            (finalHolderBalance == afterHolderBalance - collectAmount && finalCbal + collectAmount <= afterCbal)
            : true
        );
    }

    // Allow receiving Ether for funding Put
    receive() external payable {}
}

